// Enhanced input validation for multi-provider LLM routing
const inputData = $input.all()[0].json;

// Validate required fields
if (!inputData.task_description) {
  throw new Error('task_description is required for LLM routing');
}

// Extract routing parameters
const taskDescription = inputData.task_description;
const context = inputData.context || {};
const budgetConstraints = inputData.budget_constraints || { max_cost: 0.10, priority: 'balanced' };
const routingPreferences = inputData.routing_preferences || {};

// Prepare enhanced routing data
return {
  request_id: `llm_${Date.now()}`,
  task_description: taskDescription,
  context: context,
  budget_constraints: budgetConstraints,
  routing_preferences: routingPreferences,

  // Enhanced routing options
  routing_options: {
    enable_cost_optimization: true,
    enable_provider_selection: true,
    enable_fallback_routing: true,
    enable_performance_monitoring: true,

    // Provider preferences
    preferred_providers: routingPreferences.preferred_providers || [],
    excluded_providers: routingPreferences.excluded_providers || [],

    // Cost optimization
    max_budget: budgetConstraints.max_cost,
    priority: budgetConstraints.priority, // 'cost', 'speed', 'quality', 'balanced'

    // Performance requirements
    min_reliability: routingPreferences.min_reliability || 'medium',
    max_response_time: routingPreferences.max_response_time || 30000,

    // Task-specific preferences
    task_type: routingPreferences.task_type || 'auto_detect',
    complexity_level: routingPreferences.complexity_level || 'auto_detect'
  },

  // Metadata
  timestamp: new Date().toISOString(),
  source: 'enhanced_llm_router'
};

// Intelligent routing decision engine for multi-provider LLM selection
const routingData = $input.all()[0].json;
const { routing_options, task_description, budget_constraints } = routingData;

// Analyze task for optimal routing
let routing_strategy = 'intelligent';
let provider_priority = 'cost_optimized';
let fallback_strategy = 'progressive';

// Determine routing strategy based on preferences
if (routing_options.priority === 'cost') {
  routing_strategy = 'cost_optimized';
  provider_priority = 'lowest_cost_first';
} else if (routing_options.priority === 'speed') {
  routing_strategy = 'speed_optimized';
  provider_priority = 'fastest_first';
} else if (routing_options.priority === 'quality') {
  routing_strategy = 'quality_optimized';
  provider_priority = 'highest_quality_first';
} else {
  routing_strategy = 'balanced_optimization';
  provider_priority = 'intelligent_balance';
}

// Task-specific routing adjustments
const taskLower = task_description.toLowerCase();
if (taskLower.includes('code') || taskLower.includes('program')) {
  routing_strategy += '_coding_optimized';
  provider_priority = 'coding_specialized';
} else if (taskLower.includes('analyze') || taskLower.includes('research')) {
  routing_strategy += '_analysis_optimized';
  provider_priority = 'analysis_specialized';
} else if (taskLower.includes('creative') || taskLower.includes('write')) {
  routing_strategy += '_creative_optimized';
  provider_priority = 'creative_specialized';
}

// Budget-based routing adjustments
if (budget_constraints.max_cost < 0.01) {
  routing_strategy += '_ultra_budget';
  provider_priority = 'ultra_cost_effective';
} else if (budget_constraints.max_cost > 0.05) {
  routing_strategy += '_premium';
  provider_priority = 'premium_quality';
}

return {
  ...routingData,
  routing_strategy: routing_strategy,
  provider_priority: provider_priority,
  fallback_strategy: fallback_strategy,

  // Enhanced routing parameters
  routing_enhanced: {
    strategy: routing_strategy,
    priority: provider_priority,
    fallback: fallback_strategy,

    // Provider selection logic
    provider_selection: {
      primary: routing_options.preferred_providers[0] || 'auto_select',
      alternatives: routing_options.preferred_providers.slice(1) || [],
      excluded: routing_options.excluded_providers || [],
      fallback_order: ['anthropic', 'openai', 'gemini', 'openrouter']
    },

    // Cost optimization
    cost_optimization: {
      max_budget: routing_options.max_budget,
      target_efficiency: routing_options.priority === 'cost' ? 0.95 : 0.80,
      allow_overage: routing_options.priority === 'quality',
      cost_thresholds: {
        ultra_budget: 0.005,
        budget: 0.02,
        standard: 0.05,
        premium: 0.10
      }
    },

    // Performance requirements
    performance: {
      min_reliability: routing_options.min_reliability,
      max_response_time: routing_options.max_response_time,
      quality_threshold: routing_options.priority === 'quality' ? 0.95 : 0.80
    }
  }
};

// Process enhanced LLM router results and format for optimal display
const routerOutput = $input.all()[0].json;
const routingData = $input.all()[1].json;

// Check if execution was successful
if (routerOutput.error) {
  return {
    success: false,
    error: routerOutput.error,
    request_id: routingData.request_id,
    timestamp: new Date().toISOString(),
    ui_feedback: {
      message: 'LLM routing failed - please try again',
      type: 'error',
      show_retry: true
    }
  };
}

// Parse the router output
const result = JSON.parse(routerOutput.stdout || '{}');

if (result.selected_model) {
  // Enhanced multi-provider response
  return {
    success: true,

    // Core routing information
    routing_summary: {
      selected_model: result.selected_model,
      provider: result.provider,
      estimated_cost: result.estimated_cost,
      suitability_score: result.suitability_score,
      selection_reasoning: result.selection_reasoning,
      routing_strategy: routingData.routing_strategy,
      provider_priority: routingData.provider_priority
    },

    // Model capabilities and performance
    model_details: {
      capabilities: result.capabilities || [],
      strengths: result.strengths || [],
      speed: result.speed || 'unknown',
      reliability: result.reliability || 'unknown',
      max_tokens: result.max_tokens || 4096
    },

    // Alternative models for comparison
    alternatives: result.alternatives || [],

    // Cost optimization details
    cost_optimization: {
      selected_cost: result.estimated_cost,
      cost_efficiency: result.estimated_cost < 0.01 ? 'ultra_cost_effective' : 
                      result.estimated_cost < 0.02 ? 'cost_effective' : 
                      result.estimated_cost < 0.05 ? 'moderate_cost' : 'premium_cost',
      savings_vs_alternatives: result.alternatives.length > 0 ? 
        result.alternatives[0].estimated_cost - result.estimated_cost : 0,
      budget_utilization: (result.estimated_cost / routingData.routing_options.max_budget * 100).toFixed(1) + '%'
    },

    // Provider performance metrics
    provider_performance: {
      provider: result.provider,
      client_status: 'active',
      response_time: 'measured',
      reliability_score: result.reliability === 'very_high' ? 0.99 : 
                         result.reliability === 'high' ? 0.95 : 
                         result.reliability === 'medium' ? 0.85 : 0.75
    },

    // UI enhancement data for Cursor
    ui_enhancements: {
      // Visual representation of model selection
      model_visual_cue: {
        model_name: result.selected_model,
        provider: result.provider,
        icon: result.provider === 'anthropic' ? '🤖' : 
              result.provider === 'openai' ? '🧠' : 
              result.provider === 'gemini' ? '🔮' : 
              result.provider === 'openrouter' ? '🌐' : '❓',
        color: result.provider === 'anthropic' ? '#00ff00' : 
               result.provider === 'openai' ? '#0080ff' : 
               result.provider === 'gemini' ? '#ff8000' : 
               result.provider === 'openrouter' ? '#8000ff' : '#666666'
      },

      // Cost display with optimization indicators
      cost_display: {
        total_cost: result.estimated_cost,
        cost_efficiency: result.estimated_cost < 0.01 ? 'ultra_cost_effective' : 
                         result.estimated_cost < 0.02 ? 'cost_effective' : 
                         result.estimated_cost < 0.05 ? 'moderate_cost' : 'premium_cost',
        savings_indicator: result.alternatives.length > 0 ? 
          `Save $${(result.alternatives[0].estimated_cost - result.estimated_cost).toFixed(6)}` : 'No alternatives',
        budget_status: result.estimated_cost <= routingData.routing_options.max_budget ? 'within_budget' : 'over_budget'
      },

      // Performance metrics
      performance_metrics: {
        speed: result.speed || 'unknown',
        reliability: result.reliability || 'unknown',
        suitability_score: result.suitability_score,
        model_confidence: result.reliability === 'very_high' ? 0.99 : 
                          result.reliability === 'high' ? 0.95 : 
                          result.reliability === 'medium' ? 0.85 : 0.75
      },

      // Routing strategy visualization
      routing_visualization: {
        strategy: routingData.routing_strategy,
        priority: routingData.provider_priority,
        provider_count: result.alternatives.length + 1,
        optimization_level: routingData.routing_enhanced.cost_optimization.target_efficiency * 100 + '%'
      }
    },

    // Metadata
    metadata: {
      request_id: routingData.request_id,
      routing_strategy: routingData.routing_strategy,
      provider_priority: routingData.provider_priority,
      timestamp: new Date().toISOString()
    }
  };
} else {
  return {
    success: false,
    error: 'Invalid LLM router response format',
    request_id: routingData.request_id,
    timestamp: new Date().toISOString(),
    ui_feedback: {
      message: 'LLM router response format error',
      type: 'error',
      show_retry: true
    }
  };
}

// Enhanced logging and monitoring for multi-provider LLM routing
const responseData = $input.all()[0].json;
const routingData = $input.all()[1].json;

if (responseData.success) {
  const { routing_summary, cost_optimization, provider_performance } = responseData;

  console.log(`🚀 Enhanced LLM Router Success:`);
  console.log(`   Request ID: ${routingData.request_id}`);
  console.log(`   Selected Model: ${routing_summary.selected_model}`);
  console.log(`   Provider: ${routing_summary.provider}`);
  console.log(`   Cost: $${routing_summary.estimated_cost}`);
  console.log(`   Suitability Score: ${routing_summary.suitability_score.toFixed(2)}`);
  console.log(`   Routing Strategy: ${routing_summary.routing_strategy}`);
  console.log(`   Provider Priority: ${routing_summary.provider_priority}`);

  // Log cost optimization details
  console.log(`   Cost Optimization:`);
  console.log(`     Efficiency: ${cost_optimization.cost_efficiency}`);
  console.log(`     Budget Utilization: ${cost_optimization.budget_utilization}`);
  if (cost_optimization.savings_vs_alternatives > 0) {
    console.log(`     Savings: $${cost_optimization.savings_vs_alternatives.toFixed(6)}`);
  }

  // Log provider performance
  console.log(`   Provider Performance:`);
  console.log(`     Status: ${provider_performance.client_status}`);
  console.log(`     Reliability: ${provider_performance.reliability_score * 100}%`);

  // Log alternatives if available
  if (responseData.alternatives && responseData.alternatives.length > 0) {
    console.log(`   Alternatives Considered: ${responseData.alternatives.length}`);
    responseData.alternatives.forEach((alt, index) => {
      console.log(`     ${index + 1}. ${alt.model_id} (${alt.provider}) - $${alt.estimated_cost}`);
    });
  }

} else {
  console.error(`❌ Enhanced LLM Router Failed: ${responseData.error}`);
  console.error(`   Request ID: ${responseData.request_id}`);
  console.error(`   Timestamp: ${responseData.timestamp}`);
}

// Pass through the data for potential further processing
return responseData;

// Real-time status updates for enhanced LLM router
const statusData = $input.all()[0].json;
const routingData = $input.all()[1].json;

if (statusData.success) {
  // Update enhanced LLM router status
  const routerStatus = {
    status: 'active',
    last_request: new Date().toISOString(),
    request_id: routingData.request_id,
    routing_strategy: routingData.routing_strategy,
    provider_priority: routingData.provider_priority,

    // Performance metrics
    performance_metrics: {
      selected_model: statusData.routing_summary.selected_model,
      provider: statusData.routing_summary.provider,
      cost_efficiency: statusData.cost_optimization.cost_efficiency,
      suitability_score: statusData.routing_summary.suitability_score,
      reliability_score: statusData.provider_performance.reliability_score
    },

    // Cost optimization status
    cost_optimization_status: {
      total_cost: statusData.routing_summary.estimated_cost,
      budget_utilization: statusData.cost_optimization.budget_utilization,
      savings_achieved: statusData.cost_optimization.savings_vs_alternatives > 0,
      optimization_level: statusData.ui_enhancements.routing_visualization.optimization_level
    },

    // Provider status
    provider_status: {
      active_providers: ['anthropic', 'openai', 'gemini', 'openrouter'].filter(p => 
        p === statusData.routing_summary.provider || 
        statusData.alternatives.some(alt => alt.provider === p)
      ),
      selected_provider: statusData.routing_summary.provider,
      provider_performance: statusData.provider_performance.reliability_score
    }
  };

  // This could be sent to a status endpoint or stored for Cursor to query
  console.log('📊 Enhanced LLM Router Status Updated:', routerStatus);

  // Return status for potential real-time updates
  return {
    enhanced_llm_router_status: routerStatus,
    cursor_ui_update: {
      routing_summary: statusData.routing_summary,
      cost_optimization: statusData.cost_optimization,
      performance_metrics: statusData.performance_metrics,
      routing_visualization: statusData.ui_enhancements.routing_visualization
    }
  };
}

return statusData;
